// Format Voucher Text for Embedding
const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json;
  const header = payload.header || {};
  const lineItems = payload.lineItems || [];
  const summary = payload.summary || {};

  // Format voucher text for embedding - Vietnamese accounting context
  const voucherText = `
Phiếu kế toán: ${header.voucherNumber || 'N/A'}
Ngày: ${header.voucherDate || 'N/A'}
Mô tả: ${header.description || 'Không có mô tả'}
Tổng Nợ: ${summary.totalDebit || 0} VND
Tổng Có: ${summary.totalCredit || 0} VND
Kỳ kế toán: ${header.periodCode || 'N/A'}

Các bút toán:
${lineItems.map((line, idx) => `
${idx + 1}. Tài khoản: ${line.accountCode} - ${line.accountName || ''}
   Nợ: ${line.debitAmount || 0} VND
   Có: ${line.creditAmount || 0} VND
   Diễn giải: ${line.description || 'N/A'}`).join('\n')}

Thông tin liên quan:
Khách hàng: ${header.customerName || 'N/A'}
Nhà cung cấp: ${header.supplierName || 'N/A'}
  `.trim();

  results.push({
    json: {
      voucherText,
      voucherId: payload.entityId,
      companyId: payload.companyId,
      entityType: 'voucher',
      metadata: {
        voucherNumber: header.voucherNumber,
        voucherDate: header.voucherDate,
        periodId: header.periodId,
        totalDebit: summary.totalDebit,
        totalCredit: summary.totalCredit,
        createdBy: header.createdBy,
        description: header.description
      }
    }
  });
}

return results;

// Prepare Pinecone Upsert Request
const items = $input.all();
const results = [];

for (const item of items) {
  const embeddingResponse = item.json;
  const metadata = $('Format Voucher Text').first().json;

  // Extract embedding vector from Azure OpenAI response
  const embedding = embeddingResponse.data?.[0]?.embedding;

  if (!embedding) {
    throw new Error('No embedding returned from Azure OpenAI');
  }

  // Construct Pinecone upsert payload
  const pineconePayload = {
    vectors: [{
      id: `voucher-${metadata.voucherId}`,
      values: embedding,
      metadata: {
        ...metadata.metadata,
        companyId: metadata.companyId,
        entityType: metadata.entityType,
        embeddedAt: new Date().toISOString(),
        voucherText: metadata.voucherText.substring(0, 1000) // Store truncated text for context
      }
    }],
    namespace: `company-${metadata.companyId}`
  };

  results.push({ json: pineconePayload });
}

return results;

// Success Response Handler
const items = $input.all();
const metadata = $('Format Voucher Text').first().json;

return [{
  json: {
    success: true,
    message: 'Voucher embedding created successfully',
    voucherId: metadata.voucherId,
    companyId: metadata.companyId,
    voucherNumber: metadata.metadata.voucherNumber,
    embeddedAt: new Date().toISOString()
  }
}];

// Error Handler - Log failures for retry
const items = $input.all();
const error = items[0]?.json?.error || 'Unknown error';
const metadata = $('Format Voucher Text').first()?.json || {};

console.error('Embedding workflow failed:', {
  error,
  voucherId: metadata.voucherId,
  companyId: metadata.companyId,
  timestamp: new Date().toISOString()
});

return [{
  json: {
    success: false,
    error: error,
    message: 'Voucher embedding failed - will be retried',
    voucherId: metadata.voucherId,
    companyId: metadata.companyId,
    failedAt: new Date().toISOString()
  }
}];
